const $ = s => document.querySelector(s);
const grid = $("#gameGrid");
let platform = "all", genre = "all", price = "all", favorites = JSON.parse(localStorage.getItem("mgw-favorites") || "[]"), favoritesOnly = false;
const esc = s => String(s).replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
function updateFavoriteCount(){ $("#favoriteCount").textContent = favorites.length; }
function filteredGames(){
 let list = games.filter(g => {
  const q = $("#searchInput").value.trim().toLowerCase();
  const matchQ = !q || [g.name,...g.genres,g.desc].join(" ").toLowerCase().includes(q);
  const matchPlatform = platform === "all" || (platform === "both" ? g.platforms.length===2 : g.platforms.includes(platform));
  return matchQ && matchPlatform && (genre==="all" || g.genres.includes(genre)) && (price==="all" || g.price===price) && (!favoritesOnly || favorites.includes(g.id));
 });
 const sort = $("#sortSelect").value;
 if(sort==="rating") list.sort((a,b)=>b.rating-a.rating);
 else if(sort==="newest") list.sort((a,b)=>new Date(b.release)-new Date(a.release));
 else if(sort==="name") list.sort((a,b)=>a.name.localeCompare(b.name,"ko"));
 else list.sort((a,b)=>b.pop-a.pop);
 return list;
}
// 공식 App Store 상품 이미지 자동 검색: 앱스토어 API의 실제 artwork를 사용합니다.
// 최초 접속 시 인터넷이 필요하며, 이미지 주소는 브라우저 캐시에 저장됩니다.
const artworkCache = (()=>{try{return JSON.parse(localStorage.getItem("mgw-artwork")||"{}")}catch{return {}}})();
const artworkPending = new Set();
let artworkObserver;
function normalizeTitle(v){return String(v||"").toLowerCase().normalize("NFKD").replace(/[^a-z0-9가-힣ぁ-んァ-ン一-龥]/g,"");}
function pickArtwork(results, game){
 const wanted=normalizeTitle(game.name);
 const exact=results.find(x=>normalizeTitle(x.trackName)===wanted);
 if(exact)return exact.artworkUrl512||exact.artworkUrl100||exact.artworkUrl60;
 const close=results.find(x=>{const got=normalizeTitle(x.trackName);return got && (got.includes(wanted)||wanted.includes(got));});
 return close?(close.artworkUrl512||close.artworkUrl100||close.artworkUrl60):null;
}
async function fetchArtwork(game){
 if(game.imageUrl)return game.imageUrl;
 if(artworkCache[game.id]){game.imageUrl=artworkCache[game.id];return game.imageUrl;}
 if(artworkPending.has(game.id))return null;
 artworkPending.add(game.id);
 try{
  const countries=["kr","us"];
  for(const country of countries){
   const url=`https://itunes.apple.com/search?term=${encodeURIComponent(game.name)}&entity=software&limit=25&country=${country}`;
   const response=await fetch(url);
   if(!response.ok)continue;
   const data=await response.json();
   const image=pickArtwork(data.results||[],game);
   if(image){game.imageUrl=image.replace(/100x100bb/g,"512x512bb").replace(/100x100/g,"512x512");artworkCache[game.id]=game.imageUrl;
    try{localStorage.setItem("mgw-artwork",JSON.stringify(artworkCache));}catch{}
    return game.imageUrl;
   }
  }
 }catch(err){console.warn("게임 이미지 검색 실패:",game.name,err);}
 finally{artworkPending.delete(game.id);}
 return null;
}
function observeArtwork(){
 if(!artworkObserver){artworkObserver=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){const img=entry.target;artworkObserver.unobserve(img);loadArtworkInto(img);}});},{rootMargin:"220px"});}
 document.querySelectorAll("img.game-art:not([src])").forEach(img=>artworkObserver.observe(img));
}
async function loadArtworkInto(img){
 const game=games.find(x=>x.id===Number(img.dataset.artId));if(!game)return;
 const url=await fetchArtwork(game);
 if(url){img.src=url;img.onload=()=>{img.classList.add("loaded");const placeholder=img.parentElement.querySelector(".art-placeholder");if(placeholder)placeholder.hidden=true;};img.onerror=()=>{img.removeAttribute("src");};}
 else{const placeholder=img.parentElement.querySelector(".art-placeholder");if(placeholder)placeholder.innerHTML=`${esc(game.name)}<small>스토어 이미지 확인 필요</small>`;}
}

function render(){
 const list=filteredGames();
 $("#resultCount").textContent=`${list.length}개 게임${favoritesOnly?" · 즐겨찾기":""}`;
 $("#totalGames").textContent=games.length;
 grid.innerHTML=list.map(g=>`
 <article class="game-card" data-id="${g.id}" tabindex="0" aria-label="${esc(g.name)} 상세 정보 보기">
  <div class="cover" style="background:linear-gradient(135deg,${g.colors[0]},${g.colors[1]})">
   <div class="art-placeholder">${esc(g.name)}<small>공식 게임 이미지 찾는 중</small></div>
   <img class="game-art" data-art-id="${g.id}" alt="${esc(g.name)} 게임 대표 이미지" loading="lazy">
   <span class="cover-code">${g.code}</span>
   <button class="heart ${favorites.includes(g.id)?"saved":""}" data-fav="${g.id}" aria-label="즐겨찾기 ${esc(g.name)}">${favorites.includes(g.id)?"♥":"♡"}</button>
  </div>
  <div class="card-body"><div class="card-top"><span class="game-title">${esc(g.name)}</span><span class="price-tag ${g.price==="유료"?"paid":""}">${g.price}</span></div>
   <div class="genre-line">${g.genres.join(" · ")}</div><div class="card-meta"><span class="rating">★ ${g.rating.toFixed(1)}</span><span>${g.release.slice(0,4)} 출시</span></div>
   <div class="platform-tags">${g.platforms.map(p=>`<span>${p}</span>`).join("")}</div>
  </div>
 </article>`).join("");
 observeArtwork();
 $("#emptyState").hidden=list.length!==0;
}
function toast(message){const t=$("#toast");t.textContent=message;t.classList.add("show");clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove("show"),2100);}
function toggleFavorite(id){favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];localStorage.setItem("mgw-favorites",JSON.stringify(favorites));updateFavoriteCount();render();}
function openDetail(id){
 const g=games.find(x=>x.id===id); if(!g)return;
 $("#modalContent").innerHTML=`
 <div class="modal-head"><div class="modal-cover" style="background:linear-gradient(135deg,${g.colors[0]},${g.colors[1]})">${g.imageUrl?`<img src="${g.imageUrl}" alt="${esc(g.name)} 대표 이미지">`:`<span class="modal-art-placeholder">${esc(g.name)}</span>`}</div><div><h2 id="modalTitle">${esc(g.name)}</h2><div class="modal-sub">${g.genres.join(" · ")}　/　${g.platforms.join(" · ")}</div><div class="rating" style="margin-top:8px">★ ${g.rating.toFixed(1)} <span style="color:#9ba3be;font-size:10px">예시 평점</span></div></div></div>
 <p class="detail-desc">${esc(g.desc)}</p>
 <div class="detail-grid">
  <div class="detail-item"><small>가격</small><strong>${g.price}</strong></div><div class="detail-item"><small>출시일</small><strong>${g.release}</strong></div>
  <div class="detail-item"><small>게임 용량</small><strong>${g.size}</strong></div><div class="detail-item"><small>지원 기기</small><strong>${g.platforms.join(" / ")}</strong></div>
  <div class="detail-item" style="grid-column:1/-1"><small>최소 지원 사양 (참고)</small><strong>${esc(g.spec)}</strong></div>
 </div>
 <div class="store-actions"><a href="${g.play}" target="_blank" rel="noopener">Google Play에서 보기 ↗</a><a href="${g.app}" target="_blank" rel="noopener">App Store에서 보기 ↗</a></div>
 <p style="font-size:10px;color:#8992ad;margin:13px 0 0">※ 용량·사양·평점은 예시/참고 정보이며 업데이트, 기기, 지역에 따라 달라집니다. 설치 전 각 스토어에서 최신 정보를 확인하세요.</p>`;
 $("#modalBackdrop").hidden=false;document.body.style.overflow="hidden";$("#modalClose").focus();
 if(!g.imageUrl){fetchArtwork(g).then(url=>{if(!url||$("#modalBackdrop").hidden)return;const cover=$(".modal-cover");if(cover){cover.innerHTML=`<img src="${url}" alt="${esc(g.name)} 대표 이미지">`;}});}
}
function closeModal(){ $("#modalBackdrop").hidden=true;document.body.style.overflow=""; }
function randomPick(){const list=filteredGames();if(!list.length){toast("추천할 게임이 없습니다. 필터를 바꿔보세요.");return;}const g=list[Math.floor(Math.random()*list.length)];openDetail(g.id);}
$("#searchInput").addEventListener("input",render);$("#sortSelect").addEventListener("change",render);
$("#platformFilters").addEventListener("click",e=>{const b=e.target.closest("[data-platform]");if(!b)return;platform=b.dataset.platform;$("#platformFilters").querySelectorAll(".pill").forEach(x=>x.classList.toggle("active",x===b));render();});
$("#genreFilters").addEventListener("click",e=>{const b=e.target.closest("[data-genre]");if(!b)return;genre=b.dataset.genre;$("#genreFilters").querySelectorAll(".pill").forEach(x=>x.classList.toggle("active",x===b));render();});
$("#priceFilters").addEventListener("click",e=>{const b=e.target.closest("[data-price]");if(!b)return;price=b.dataset.price;$("#priceFilters").querySelectorAll(".pill").forEach(x=>x.classList.toggle("active",x===b));render();});
grid.addEventListener("click",e=>{const fav=e.target.closest("[data-fav]");if(fav){e.stopPropagation();toggleFavorite(Number(fav.dataset.fav));return;}const card=e.target.closest("[data-id]");if(card)openDetail(Number(card.dataset.id));});
grid.addEventListener("keydown",e=>{if((e.key==="Enter"||e.key===" ")&&e.target.matches(".game-card")){e.preventDefault();openDetail(Number(e.target.dataset.id));}});
$("#resetFilters").addEventListener("click",()=>{platform=genre=price="all";favoritesOnly=false;$("#searchInput").value="";$("#sortSelect").value="popular";document.querySelectorAll(".pills").forEach(group=>group.querySelectorAll(".pill").forEach((b,i)=>b.classList.toggle("active",i===0)));render();});
$("#showFavorites").addEventListener("click",()=>{favoritesOnly=!favoritesOnly;$("#showFavorites").style.borderColor=favoritesOnly?"#a78bfa":"";render();$("#games").scrollIntoView({behavior:"smooth"});});
$("#randomButton").addEventListener("click",randomPick);$("#randomButtonBottom").addEventListener("click",randomPick);
$("#modalClose").addEventListener("click",closeModal);$("#modalBackdrop").addEventListener("click",e=>{if(e.target===$("#modalBackdrop"))closeModal();});document.addEventListener("keydown",e=>{if(e.key==="Escape")closeModal();});
updateFavoriteCount();render();

